<?php if($view==='blog'): $page=max(1,(int)($_GET['page']??1));$where='type="post" AND status="publish"';$params=[];if(!empty($_GET['category'])){$where.=' AND category_id=(SELECT id FROM content_categories WHERE slug=?)';$params[]=$_GET['category'];}$posts=rows('SELECT * FROM content WHERE '.$where.' ORDER BY published_at DESC LIMIT 9 OFFSET '.(($page-1)*9),$params); ?>
<div class="blog-area py-90"><div class="container"><div class="mb-4"><a class="btn" href="<?= url('blog.php') ?>">All articles</a><?php foreach(rows('SELECT * FROM content_categories ORDER BY name') as $c): ?><a class="btn" href="<?= url('blog.php?category='.rawurlencode($c['slug'])) ?>"><?= h($c['name']) ?></a><?php endforeach; ?></div><div class="row"><?php foreach($posts as $b): ?><div class="col-md-6 col-lg-4"><div class="blog-item"><?php if($b['image']): ?><div class="blog-item-img"><img loading="lazy" src="<?= h(url($b['image'])) ?>" alt="<?= h($b['title']) ?>"></div><?php endif; ?><div class="blog-item-info"><div class="blog-item-meta"><span><?= h(date('j M Y',strtotime($b['published_at']))) ?></span></div><h3 class="blog-title"><a href="<?= url('blog-single.php?slug='.rawurlencode($b['slug'])) ?>"><?= h($b['title']) ?></a></h3><p><?= h(mb_substr($b['excerpt']?:strip_tags($b['body']),0,140)) ?></p><a class="theme-btn" href="<?= url('blog-single.php?slug='.rawurlencode($b['slug'])) ?>">Read more</a></div></div></div><?php endforeach; ?></div><?php if($page>1): ?><a class="theme-btn" href="?<?= h(http_build_query(array_merge($_GET,['page'=>$page-1]))) ?>">Previous</a><?php endif; ?> <?php if(count($posts)===9): ?><a class="theme-btn" href="?<?= h(http_build_query(array_merge($_GET,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></div></div>
<?php elseif($view==='contact'): ?><div class="contact-area py-90"><div class="container"><div class="row"><div class="col-lg-5"><div class="contact-info"><h3 class="mb-4">Get in touch</h3><p><?= h(setting('address')) ?></p><p class="mt-3"><a href="tel:<?= h(setting('phone')) ?>"><?= h(setting('phone').' / '.setting('phone_alt')) ?></a></p><p><a href="mailto:<?= h(setting('email')) ?>"><?= h(setting('email')) ?></a></p><p><?= h(setting('business_hours')) ?></p></div></div><div class="col-lg-7"><div class="contact-form"><h3 class="mb-4">Send a message</h3><form method="post" class="store-form"><?= csrf_field() ?><input type="hidden" name="action" value="contact"><?php foreach(['name','email','subject'] as $k): ?><label for="<?= $k ?>"><?= ucfirst($k) ?></label><input id="<?= $k ?>" type="<?= $k==='email'?'email':'text' ?>" name="<?= $k ?>" required value="<?= h($_POST[$k]??'') ?>"><?php endforeach; ?><label for="message">Message</label><textarea id="message" name="message" required rows="5" maxlength="5000"><?= h($_POST['message']??'') ?></textarea><button class="theme-btn">Send message</button></form></div></div></div></div></div>
<?php elseif($view==='missing'): ?><div class="error-area py-90"><div class="container text-center"><h2>We could not find this page.</h2><a href="<?= url('shop-grid.php') ?>" class="theme-btn mt-4">Browse the shop</a></div></div>
<?php else: ?><div class="blog-single-area py-90"><div class="container"><article class="blog-details store-content"><h2 class="mb-4"><?= h($post['title']) ?></h2><?php if($view==='article'): ?><p><?= h($post['author']) ?> · <?= h(date('j M Y',strtotime($post['published_at']))) ?></p><?php endif; ?><?php if($post['image']): ?><img class="mb-4" src="<?= h(url($post['image'])) ?>" alt="<?= h($post['title']) ?>"><?php endif; ?><?= $post['body'] ?></article></div></div><?php endif; ?>
